r['Distribution']=resource('AWS::CloudFront::Distribution',{'DistributionConfig':{'Enabled':True,'Comment':'CareWatch NY public financial assistance observatory','DefaultRootObject':'index.html','HttpVersion':'http2and3','IPV6Enabled':True,'PriceClass':'PriceClass_100','Origins':[{'Id':'PrivateSite','DomainName':att('SiteBucket','RegionalDomainName'),'OriginPath':'/site','S3OriginConfig':{'OriginAccessIdentity':''},'OriginAccessControlId':ref('OriginAccess')}],'DefaultCacheBehavior':{'TargetOriginId':'PrivateSite','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD'],'CachedMethods':['GET','HEAD'],'Compress':True,'CachePolicyId':'658327ea-f89d-4fab-a63d-7e88639e58f6','ResponseHeadersPolicyId':ref('SecurityHeaders')},'CacheBehaviors':[{'PathPattern':'api/*','TargetOriginId':'PrivateSite','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD'],'CachedMethods':['GET','HEAD'],'Compress':True,'CachePolicyId':'4135ea2d-6df8-44a3-9df3-4b5a84be39ad','ResponseHeadersPolicyId':ref('SecurityHeaders')},{'PathPattern':'data/*','TargetOriginId':'PrivateSite','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD'],'CachedMethods':['GET','HEAD'],'Compress':True,'CachePolicyId':'4135ea2d-6df8-44a3-9df3-4b5a84be39ad','ResponseHeadersPolicyId':ref('SecurityHeaders')}],'ViewerCertificate':{'CloudFrontDefaultCertificate':True}}},'Public HTTPS dashboard; uncached data paths show new monitoring results',['No private snapshot or state object may be exposed'])
